const fs=require('fs'),path=require('path'),puppeteer=require('puppeteer-core');
const OUT=process.env.PHASE19_PERF_OUT||'/tmp/phase19-perf-diag';
const beforeBase='http://127.0.0.1:8000/';const afterBase='http://127.0.0.1:8001/';fs.mkdirSync(OUT,{recursive:true});const sleep=ms=>new Promise(r=>setTimeout(r,ms));
async function run(browser,base,label,rep){const ctx=await browser.createBrowserContext();const page=await ctx.newPage();await page.setViewport({width:390,height:844});await page.setCacheEnabled(false);const requests=[];const responses=[];const cdp=await page.target().createCDPSession();await cdp.send('Network.enable');cdp.on('Network.requestWillBeSent',e=>{if(e.type!=='Other'||!e.request.url.startsWith('data:'))requests.push({url:e.request.url,type:e.type})});cdp.on('Network.responseReceived',e=>responses.push({url:e.response.url,status:e.response.status,mime:e.response.mimeType}));await page.goto(base+'contact.html',{waitUntil:'load',timeout:45000});await sleep(3000);const perf=await page.evaluate(()=>performance.getEntriesByType('resource').map(x=>({url:x.name,initiator:x.initiatorType,transfer:x.transferSize||0,decoded:x.decodedBodySize||0})));await ctx.close();const norm=u=>u.replace(base,'LOCAL/');return{label,rep,requests:requests.map(x=>({...x,url:norm(x.url)})),responses:responses.map(x=>({...x,url:norm(x.url)})),perf:perf.map(x=>({...x,url:norm(x.url)}))};}
(async()=>{const browser=await puppeteer.launch({executablePath:process.env.CHROME,headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});const rows=[];try{for(let i=1;i<=5;i++)rows.push(await run(browser,beforeBase,'before',i));for(let i=1;i<=5;i++)rows.push(await run(browser,afterBase,'after',i));}finally{await browser.close();}const sets={};for(const label of ['before','after']){const rs=rows.filter(x=>x.label===label);sets[label]=rs.map(x=>[...new Set(x.requests.map(r=>r.url))].sort());}
const union=a=>[...new Set(a.flat())].sort();const beforeUnion=union(sets.before),afterUnion=union(sets.after);const report={route:'contact.html',viewport:'390x844',repetitionsPerSide:5,beforeRequestCounts:rows.filter(x=>x.label==='before').map(x=>x.requests.length),afterRequestCounts:rows.filter(x=>x.label==='after').map(x=>x.requests.length),beforeUnion,afterUnion,added:afterUnion.filter(x=>!beforeUnion.includes(x)),removed:beforeUnion.filter(x=>!afterUnion.includes(x)),rows};fs.writeFileSync(path.join(OUT,'contact-performance-diagnostic.json'),JSON.stringify(report,null,2));console.log(JSON.stringify({...report,rows:undefined},null,2));if(report.added.length||report.removed.length)process.exit(1);})();
